function chalkProcess(data,w,h,opts){
  opts=opts||{};
  var thr=opts.thr!=null?opts.thr:36;
  if(thr<0)thr=0; else if(thr>150)thr=150;
  var lum=new Float32Array(w*h);
  for(var i=0,y=0;y<h;y++) for(var x=0;x<w;x++,i++){ var p=(y*w+x)*4; lum[i]=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  function L(x,y){ if(x<0)x=0; else if(x>w-1)x=w-1; if(y<0)y=0; else if(y>h-1)y=h-1; return lum[y*w+x]; }
  var bg=[18,22,20];
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var gx=L(x-1,y-1)+2*L(x-1,y)+L(x-1,y+1)-L(x+1,y-1)-2*L(x+1,y)-L(x+1,y+1);
    var gy=L(x-1,y-1)+2*L(x,y-1)+L(x+1,y-1)-L(x-1,y+1)-2*L(x,y+1)-L(x+1,y+1);
    var e=Math.sqrt(gx*gx+gy*gy);
    var cov=e>thr?Math.min(1,(e-thr)/50):0;
    var nz=((Math.sin(x*1.3)+Math.sin(y*1.7))*0.5+0.5);
    var chalk=235*(0.7+0.3*nz);
    out[p]=bg[0]*(1-cov)+chalk*cov;
    out[p+1]=bg[1]*(1-cov)+chalk*cov;
    out[p+2]=bg[2]*(1-cov)+chalk*cov;
    out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={chalkProcess:chalkProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ChalkForgePure = EXPORTS; }
